70	 */
71	
72	@RestController
73	@CrossOrigin(exposedHeaders = "errors, content-type")
74	@RequestMapping("/api")
75	public class OwnerRestControllerV1 implements OwnersApi {
76	
77	    /**
78	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
79	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
80	     * stored lower-cased.
81	     */
82	    private static final Pattern EMAIL_PATTERN =
83	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
84	
85	    /** A well-formed postcode: exactly four digits. */
86	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
87	
88	    /**
89	     * Email domains belonging to disposable-address providers. An owner whose email domain (the part
90	     * after the '@', compared case-insensitively) is one of these is rejected: such addresses are
91	     * throwaway and unsuitable for a durable owner record.
92	     */
93	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
94	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
95	
96	    /**
97	     * Region -&gt; inclusive 4-digit postcode range {@code {low, high}}. A postcode supplied for an
98	     * owner whose city maps to one of these regions (see {@link LocalityLookup}) must fall within the
99	     * region's range; a city with no known region ({@code "UNKNOWN"}) accepts any 4-digit postcode.
100	     */
101	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
102	        "NSW", new int[] {2000, 2099},
103	        "VIC", new int[] {3000, 3099},
104	        "QLD", new int[] {4000, 4099});
105	
106	    /** Dedicated audit logger; one line is emitted per successful owner create. */
107	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
108	
109	    /** Dedicated notification logger; one welcome line is emitted per successful owner create. */
110	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
111	
112	    /**
113	     * Monotonically increasing sequence for structured owner-create events, shared across all creates
114	     * regardless of which request or thread performs them. The first event carries {@code seq=1}.
115	     */
116	    private static final AtomicInteger OWNER_CREATE_SEQUENCE = new AtomicInteger();
117	
118	    /** Serializer for the immutable structured audit event. */
119	    private static final ObjectMapper AUDIT_EVENT_MAPPER = JsonMapper.builder().build();
120	
121	    /**
122	     * The maximum number of owners a single city may contain. Once a city already holds this many
123	     * owners, any further create naming that city is rejected as a conflict.
124	     */
125	    private static final int MAX_OWNERS_PER_CITY = 50;
126	
127	    /**
128	     * The number of owners a city must already hold before a response carries a capacity warning.
129	     * Once a city holds at least this many owners (but fewer than {@link #MAX_OWNERS_PER_CITY}),
130	     * responses naming that city set {@code capacityWarning} true, signalling that the city is
131	     * approaching its per-city capacity limit.
132	     */
133	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
134	
135	    /**
136	     * The maximum number of owners that may be registered in a single day. Once this many owners
137	     * already carry today's registration date, any further create is rejected as too many requests.
138	     */
139	    private static final int MAX_OWNERS_PER_DAY = 100;
140	
141	    /**
142	     * The number of owners that must already be registered on today's business day before a response
143	     * carries a bulk-signup warning. Once more than this many owners already carry today's
144	     * registration date, responses set {@code bulkSignupWarning} true.
145	     */
146	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
147	
148	    /**
149	     * The fixed list of public holidays. A registration date that lands on one of these dates is
150	     * rolled forward to the next non-holiday business day, just as a weekend date is.
151	     */
152	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
153	        LocalDate.of(2026, 1, 1),
154	        LocalDate.of(2026, 1, 26),
155	        LocalDate.of(2026, 4, 25),
156	        LocalDate.of(2026, 12, 25),
157	        LocalDate.of(2026, 12, 28));
158	
159	    private final ClinicService clinicService;
160	
161	    private final OwnerMapper ownerMapper;
162	
163	    private final PetMapper petMapper;
164	
165	    private final VisitMapper visitMapper;
166	
167	    public OwnerRestControllerV1(ClinicService clinicService,
168	                                 OwnerMapper ownerMapper,
169	                                 PetMapper petMapper,
170	                                 VisitMapper visitMapper) {
171	        this.clinicService = clinicService;
172	        this.ownerMapper = ownerMapper;
173	        this.petMapper = petMapper;
174	        this.visitMapper = visitMapper;
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
180	        Collection<Owner> owners;
181	        if (lastName != null) {
182	            owners = this.clinicService.findOwnerByLastName(lastName);
183	        } else {
184	            owners = this.clinicService.findAllOwners();
185	        }
186	        if (owners.isEmpty()) {
187	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
188	        }
189	        owners.forEach(owner -> owner.setHouseholdMemberCount(countHouseholdMembers(owner)));
190	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
196	        Owner owner = this.clinicService.findOwnerById(ownerId);
197	        if (owner == null) {
198	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	        }
200	        OwnerDto ownerDto = toOwnerDto(owner);
201	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
202	        ownerDto.setCapacityWarning(isCapacityWarningActive(owner.getCity()));
203	        ownerDto.setRiskFlag(isRiskFlagActive(owner));
204	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
210	        String idempotencyKey = currentIdempotencyKey();
211	        if (idempotencyKey != null) {
212	            Owner alreadyCreated = findOwnerByIdempotencyKey(idempotencyKey);
213	            if (alreadyCreated != null) {
214	                OwnerDto existingDto = toOwnerDto(alreadyCreated);
215	                existingDto.setBulkSignupWarning(isBulkSignupWarningActive());
216	                existingDto.setCapacityWarning(isCapacityWarningActive(alreadyCreated.getCity()));
217	                existingDto.setRiskFlag(isRiskFlagActive(alreadyCreated));
218	                return new ResponseEntity<>(existingDto, HttpStatus.OK);
219	            }
220	        }
221	        validateRequiredOwnerFields(ownerFieldsDto);
222	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
223	        LocalDate suppliedOrDefaultDate =
224	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
225	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
226	        rejectDailyLimitExceeded(registrationDate);
227	        rejectCityAtCapacity(ownerFieldsDto.getCity());
228	        HttpHeaders headers = new HttpHeaders();
229	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
230	        validatePostcode(owner.getCity(), owner.getPostcode());
231	        applyAddress(owner);
232	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
233	        owner.setTelephone(normalizedTelephone);
234	        boolean declaredHouseholdMember = applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
235	        owner.setEmail(normalizeEmail(owner.getEmail()));
236	        rejectDuplicateIdentity(owner);
237	        applyPossibleDuplicate(owner, declaredHouseholdMember);
238	        owner.setRegistrationDate(registrationDate);
239	        owner.setMemberId(generateMemberId(owner.getPostcode(), owner.getCity(), normalizedTelephone,
240	            owner.getLastName(), owner.getRegistrationDate()));
241	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
242	        owner.setIdempotencyKey(idempotencyKey);
243	        applyMembershipLevelCeiling(owner);
244	        this.clinicService.saveOwner(owner);
245	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
246	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
247	        emitOwnerCreatedEvent(owner);
248	        enqueueWelcomeNotification(owner);
249	        OwnerDto ownerDto = toOwnerDto(owner);
250	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
251	        ownerDto.setCapacityWarning(isCapacityWarningActive(owner.getCity()));
252	        ownerDto.setRiskFlag(isRiskFlagActive(owner));
253	        headers.setLocation(UriComponentsBuilder.newInstance()
254	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
255	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
256	    }
257	
258	    /**
259	     * Emits the immutable structured {@code OWNER_CREATED} event on the {@code AUDIT} logger, in
260	     * addition to the human-readable audit line. The event carries a monotonically increasing sequence
261	     * number, the owner id, the owner's current primary identifier (the member id) and the derived
262	     * membership level, serialized as a compact JSON object.
263	     *
264	     * @param owner the just-saved owner
265	     */
266	    private void emitOwnerCreatedEvent(Owner owner) {
267	        OwnerCreatedEvent event = OwnerCreatedEvent.of(OWNER_CREATE_SEQUENCE.incrementAndGet(),
268	            owner.getId(), owner.getMemberId(), owner.getMembershipLevel());
269	        AUDIT.info(AUDIT_EVENT_MAPPER.writeValueAsString(event));
270	    }
271	
272	    /**
273	     * Enqueues a welcome notification for a just-created owner by emitting a single line on the
274	     * {@code NOTIFY} logger carrying the owner id and the owner's member id.
275	     *
276	     * @param owner the just-saved owner
277	     */
278	    private void enqueueWelcomeNotification(Owner owner) {
279	        NOTIFY.info("Welcome notification queued: id={} memberId={}", owner.getId(), owner.getMemberId());
280	    }
281	
282	    /**
283	     * The idempotency key supplied on the current create request, read from its {@code Idempotency-Key}
284	     * header. A blank value is treated as absent.
285	     *
286	     * @return the trimmed {@code Idempotency-Key} header, or {@code null} when it is absent or blank
287	     */
288	    private String currentIdempotencyKey() {
289	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
290	            String header = attributes.getRequest().getHeader("Idempotency-Key");
291	            if (header != null && !header.isBlank()) {
292	                return header.trim();
293	            }
294	        }
295	        return null;
296	    }
297	
298	    /**
299	     * Finds the owner originally created under the given idempotency key, so a repeated create carrying
300	     * an already-seen key returns that owner instead of creating a duplicate. The lowest-id match is
301	     * returned when more than one owner somehow carries the key.
302	     *
303	     * @param idempotencyKey the create request's idempotency key
304	     * @return the owner first created under the key, or {@code null} when the key has not been seen
305	     */
306	    private Owner findOwnerByIdempotencyKey(String idempotencyKey) {
307	        return this.clinicService.findAllOwners().stream()
308	            .filter(existing -> idempotencyKey.equals(existing.getIdempotencyKey()))
309	            .min(java.util.Comparator.comparing(Owner::getId))
310	            .orElse(null);
311	    }
312	
313	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
314	    @Override
315	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
316	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
317	        if (currentOwner == null) {
318	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
319	        }
320	        currentOwner.setAddress(ownerFieldsDto.getAddress());
321	        currentOwner.setCity(ownerFieldsDto.getCity());
322	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
323	        currentOwner.setLastName(ownerFieldsDto.getLastName());
324	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
325	        this.clinicService.saveOwner(currentOwner);
326	        return new ResponseEntity<>(toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
327	    }
328	
329	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
330	    @Transactional
331	    @Override
332	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
333	        Owner owner = this.clinicService.findOwnerById(ownerId);
334	        if (owner == null) {
335	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
336	        }
337	        owner.setDeleted(true);
338	        this.clinicService.saveOwner(owner);
339	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
340	    }
341	
342	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
343	    @Override
344	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
345	        Owner owner = this.clinicService.findOwnerById(ownerId);
346	        if (owner == null) {
347	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
348	        }
349	        HttpHeaders headers = new HttpHeaders();
350	        Pet pet = petMapper.toPet(petFieldsDto);
351	        owner.setId(ownerId);
352	        pet.setOwner(owner);
353	        pet.getType().setName(null);
354	        this.clinicService.savePet(pet);
355	        PetDto petDto = petMapper.toPetDto(pet);
356	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
357	            .buildAndExpand(pet.getId()).toUri());
358	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
359	    }
360	
361	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
362	    @Override
363	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
364	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
365	        if (currentOwner != null) {
366	            Pet currentPet = this.clinicService.findPetById(petId);
367	            if (currentPet != null) {
368	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
369	                currentPet.setName(petFieldsDto.getName());
370	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
371	                this.clinicService.savePet(currentPet);
372	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
373	            }
374	        }
375	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
376	    }
377	
378	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
379	    @Override
380	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
381	        HttpHeaders headers = new HttpHeaders();
382	        Visit visit = visitMapper.toVisit(visitFieldsDto);
383	        Pet pet = new Pet();
384	        pet.setId(petId);
385	        visit.setPet(pet);
386	        this.clinicService.saveVisit(visit);
387	        VisitDto visitDto = visitMapper.toVisitDto(visit);
388	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
389	            .buildAndExpand(visit.getId()).toUri());
390	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
391	    }
392	
393	
394	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
395	    @Override
396	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
397	        Owner owner = this.clinicService.findOwnerById(ownerId);
398	        if (owner != null) {
399	            Pet pet = owner.getPet(petId);
400	            if (pet != null) {
401	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
402	            }
403	        }
404	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
405	    }
406	
407	    /**
408	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
409	     * offending field is collected so the caller learns exactly which values must be supplied.
410	     *
411	     * @param ownerFieldsDto the submitted owner payload
412	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
413	     *         telephone is missing or blank
414	     */
