589	     * {@link #DISPOSABLE_EMAIL_DOMAINS} without its top-level label (e.g. {@code "mailinator.com"} yields
590	     * {@code "mailinator"}). Used to detect disposable-adjacent domains.
591	     */
592	    private static final java.util.Set<String> DISPOSABLE_EMAIL_BASE_LABELS =
593	        DISPOSABLE_EMAIL_DOMAINS.stream()
594	            .map(domain -> domain.substring(0, domain.indexOf('.')))
595	            .collect(java.util.stream.Collectors.toUnmodifiableSet());
