597	    /**
598	     * Reports whether the given email's domain is disposable-adjacent: near enough to a known
599	     * disposable-address provider ({@link #DISPOSABLE_EMAIL_DOMAINS}) to be treated as a risk without
600	     * being an exact blocklist match (an exact match is already rejected on create, so it is never
601	     * stored). A domain is disposable-adjacent when, compared case-insensitively, it is a subdomain of a
602	     * blocklisted domain (e.g. {@code "mail.mailinator.com"}) or its registrable label - the label
603	     * immediately before its top-level label - equals a known provider's base label (e.g.
604	     * {@code "mailinator.net"} or {@code "tempmail.io"}). An absent (null or blank) email is never
605	     * disposable-adjacent.
606	     *
607	     * @param email the owner's stored (lower-cased) email, or {@code null} when none is present
608	     * @return {@code true} when the email's domain is disposable-adjacent, otherwise {@code false}
609	     */
610	    private boolean isDisposableAdjacentEmail(String email) {
611	        if (email == null || email.isBlank()) {
612	            return false;
613	        }
614	        int at = email.indexOf('@');
615	        if (at < 0 || at == email.length() - 1) {
616	            return false;
617	        }
618	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
619	        for (String blocked : DISPOSABLE_EMAIL_DOMAINS) {
620	            if (domain.endsWith("." + blocked)) {
621	                return true;
622	            }
623	        }
624	        String[] labels = domain.split("\\.");
625	        if (labels.length >= 2) {
626	            String registrableLabel = labels[labels.length - 2];
627	            return DISPOSABLE_EMAIL_BASE_LABELS.contains(registrableLabel);
628	        }
629	        return false;
630	    }
