632	    private LocalDate toBusinessDay(LocalDate date) {
633	        LocalDate adjusted = switch (date.getDayOfWeek()) {
634	            case SATURDAY -> date.plusDays(2);
635	            case SUNDAY -> date.plusDays(1);
636	            default -> date;
637	        };
638	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
639	            adjusted = adjusted.plusDays(1);
640	        }
641	        return adjusted;
642	    }
