661	    /**
662	     * Builds an owner's unified member id, formatted '&lt;REGION&gt;&lt;FY&gt;&lt;HASH8&gt;&lt;CHK&gt;'.
663	     * REGION is the region code derived from the owner's postcode (falling back to their city; see
664	     * {@link LocalityLookup}); FY is the two-digit fiscal year (the fiscal year starts on 1 July) that
665	     * the business-day-adjusted registrationDate falls in; HASH8 is the first 8 upper-case hex
666	     * characters of the SHA-256 digest over the owner's normalized telephone concatenated with their
667	     * last name (the same hash used by the region-and-hash identity); and CHK is a single Luhn check
668	     * digit computed over the digits of '&lt;REGION&gt;&lt;FY&gt;&lt;HASH8&gt;' (e.g. 'NSW271A2B3C4D5').
669	     * When the computed id collides with an existing owner's member id it is de-duplicated by appending
670	     * '-&lt;n&gt;' with the smallest {@code n} of 2 or more that makes it unique.
671	     *
672	     * @param postcode the owner's postcode, used first to derive the region
673	     * @param city the owner's city, used to derive the region when the postcode maps to none
674	     * @param normalizedTelephone the owner's normalized (E.164) telephone
675	     * @param lastName the owner's last name
676	     * @param registrationDate the owner's business-day-adjusted registration date
677	     * @return the formatted, de-duplicated member id
678	     */
679	    private String generateMemberId(String postcode, String city, String normalizedTelephone, String lastName,
680	            LocalDate registrationDate) {
681	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
682	        String fy = String.format("%02d", Owner.fiscalYear(registrationDate) % 100);
683	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
684	        String base = region + fy + hash8;
685	        String baseId = base + luhnCheckDigit(base);
686	        return deduplicateMemberId(baseId);
687	    }
688	
689	    /**
690	     * De-duplicates a computed member id against every existing owner's member id. When no existing
691	     * owner already carries the base id it is returned unchanged; otherwise '-&lt;n&gt;' is appended
692	     * with the smallest {@code n} of 2 or more that yields an id no existing owner holds.
693	     *
694	     * @param baseId the computed, formatted member id before de-duplication
695	     * @return the base id when unique, otherwise the base id suffixed with '-&lt;n&gt;'
696	     */
697	    private String deduplicateMemberId(String baseId) {
698	        java.util.Set<String> existingIds = this.clinicService.findAllOwners().stream()
699	            .map(Owner::getMemberId)
700	            .filter(java.util.Objects::nonNull)
701	            .collect(java.util.stream.Collectors.toSet());
702	        if (!existingIds.contains(baseId)) {
703	            return baseId;
704	        }
705	        int n = 2;
706	        while (existingIds.contains(baseId + "-" + n)) {
707	            n++;
708	        }
709	        return baseId + "-" + n;
710	    }
