712	    /**
713	     * The single Luhn check digit (0-9) computed over the digits contained in the given string.
714	     * Non-digit characters are ignored and the rightmost digit is doubled.
715	     *
716	     * @param value the string whose digits the check digit is computed over
717	     * @return the Luhn check digit (0-9)
718	     */
719	    private int luhnCheckDigit(String value) {
720	        int sum = 0;
721	        boolean dbl = true;
722	        for (int i = value.length() - 1; i >= 0; i--) {
723	            char c = value.charAt(i);
724	            if (c < '0' || c > '9') {
725	                continue;
726	            }
727	            int d = c - '0';
728	            if (dbl) {
729	                d *= 2;
730	                if (d > 9) {
731	                    d -= 9;
732	                }
733	            }
734	            sum += d;
735	            dbl = !dbl;
736	        }
737	        return (10 - (sum % 10)) % 10;
738	    }
