740	    /**
741	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
742	     * country calling code. Australia ('+61') uses 9 national digits and the North American
743	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
744	     * E.164 length (8 to 15 digits overall).
745	     */
746	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
747	        java.util.Map.of("61", 9, "1", 10);
748	
749	    /**
750	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
751	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
752	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
753	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
754	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
755	     * E.164 string is what gets stored and returned.
756	     *
757	     * @param telephone the raw telephone value from the request
758	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
759	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
760	     *         national number has the wrong length for its country code
761	     */
762	    private String normalizeTelephone(String telephone) {
763	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
764	        String e164;
765	        if (cleaned.startsWith("+")) {
766	            e164 = cleaned;
767	        } else {
768	            String national = cleaned;
769	            if (national.startsWith("0")) {
770	                national = national.substring(1);
771	            }
772	            e164 = "+61" + national;
773	        }
774	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
775	            throw new InvalidOwnerFieldsException(List.of("telephone"));
776	        }
777	        validateNationalNumberLength(e164);
778	        return e164;
779	    }
780	
781	    /**
782	     * Rejects an E.164 telephone whose national number does not have the exact length its country
783	     * calling code requires. The digits after the leading '+' are split into the longest matching
784	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
785	     * code is known and the national number's length differs from the required count the telephone is
786	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
787	     *
788	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
789	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
790	     */
791	    private void validateNationalNumberLength(String e164) {
792	        String digits = e164.substring(1);
793	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
794	            String countryCode = digits.substring(0, codeLength);
795	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
796	            if (requiredNationalLength != null) {
797	                int nationalLength = digits.length() - codeLength;
798	                if (nationalLength != requiredNationalLength) {
799	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
800	                }
801	                return;
802	            }
803	        }
804	    }
