890	    /**
891	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
892	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
893	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
894	     * normalized form is what gets stored, returned and used for every address comparison (the
895	     * required-field check, household duplicate detection and the shared household id).
896	     *
897	     * @param address the raw address value from the request, or {@code null}
898	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
899	     */
900	    private String normalizeAddress(String address) {
901	        if (address == null) {
902	            return "";
903	        }
904	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
905	        if (collapsed.isEmpty()) {
906	            return "";
907	        }
908	        String[] tokens = collapsed.split(" ");
909	        for (int i = 0; i < tokens.length; i++) {
910	            switch (tokens[i]) {
911	                case "ST" -> tokens[i] = "STREET";
912	                case "RD" -> tokens[i] = "ROAD";
913	                case "AVE" -> tokens[i] = "AVENUE";
914	                default -> { }
915	            }
916	        }
917	        return String.join(" ", tokens);
918	    }
919	
920	    /**
921	     * Rejects an owner create whose {@code identityKey} exactly matches a non-deleted existing owner's.
922	     * The identity key - the SHA-256 hex digest over the owner's normalized telephone, lower-cased email
923	     * (empty when none) and the Soundex code of its last name, joined by {@code '|'} - is the single
924	     * derived value used for duplicate detection; owners flagged deleted are ignored. Only a whole-key
925	     * match is a conflict, so two owners with the same last name and postcode but different telephones
926	     * have different keys and are both allowed; only an owner whose entire key is identical is a
927	     * duplicate.
928	     *
929	     * @param owner the owner being created, with its telephone, email and last name already resolved
930	     * @throws DuplicateOwnerIdentityException if another non-deleted owner already has this exact identity key
931	     */
932	    private void rejectDuplicateIdentity(Owner owner) {
933	        String identityKey = owner.getIdentityKey();
934	        boolean inUse = this.clinicService.findAllOwners().stream()
935	            .filter(existing -> !existing.isDeleted())
936	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
937	        if (inUse) {
938	            throw new DuplicateOwnerIdentityException(identityKey);
939	        }
940	    }
941	
942	    /**
943	     * Flags an owner being created as a possible (soft) duplicate. A soft match is an existing owner
944	     * whose last name shares this owner's Soundex code and whose postcode matches, yet whose
945	     * {@code identityKey} differs; such an owner is not a hard duplicate (its whole identity key
946	     * differs) and is still created. When at least one soft match exists, {@code possibleDuplicate} is
947	     * set true and {@code possibleDuplicateOf} to the lowest-id match; otherwise {@code possibleDuplicate}
948	     * is false and {@code possibleDuplicateOf} is left unset.
949	     * <p>
950	     * A declared household member - an owner that acknowledged sharing an existing household via
951	     * {@code sharesHousehold} - is never flagged: having deliberately joined the household it is not a
952	     * suspected duplicate, so {@code possibleDuplicate} is set false without inspecting other owners.
953	     *
954	     * @param owner the owner being created, with its last name, postcode, email and normalized
955	     *        telephone resolved
956	     * @param declaredHouseholdMember whether the owner joined an existing household by acknowledging it
957	     */
958	    private void applyPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
959	        if (declaredHouseholdMember) {
960	            owner.setPossibleDuplicate(false);
961	            return;
962	        }
963	        String soundex = Owner.soundex(owner.getLastName());
964	        String postcode = owner.getPostcode();
965	        String identityKey = owner.getIdentityKey();
966	        Owner match = null;
967	        if (postcode != null && !postcode.isBlank()) {
968	            match = this.clinicService.findAllOwners().stream()
969	                .filter(existing -> !existing.isDeleted())
970	                .filter(existing -> Owner.soundex(existing.getLastName()).equals(soundex))
971	                .filter(existing -> postcode.equals(existing.getPostcode()))
972	                .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
973	                .min(java.util.Comparator.comparing(Owner::getId))
974	                .orElse(null);
975	        }
976	        if (match != null) {
977	            owner.setPossibleDuplicate(true);
978	            owner.setPossibleDuplicateOf(match.getId());
979	        } else {
980	            owner.setPossibleDuplicate(false);
981	        }
982	    }
983	
984	    /**
985	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
986	     * household member count} for the response.
987	     *
988	     * @param owner the owner to map
989	     * @return the mapped owner DTO
990	     */
991	    private OwnerDto toOwnerDto(Owner owner) {
992	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
993	        return ownerMapper.toOwnerDto(owner);
994	    }
995	
996	    /**
997	     * Counts the members of the given owner's household - the owners that share this owner's
998	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
999	     * is {@code null}) is its own sole member, so the count is one.
1000	     *
1001	     * @param owner the owner whose household is being sized
1002	     * @return the number of owners sharing this owner's household (one when it has no household)
1003	     */
1004	    private int countHouseholdMembers(Owner owner) {
1005	        String householdId = owner.getHouseholdId();
1006	        if (householdId == null) {
1007	            return 1;
1008	        }
1009	        return (int) this.clinicService.findAllOwners().stream()
1010	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
1011	            .count();
1012	    }
1013	
1014	    /**
1015	     * Caps the membership level of an owner being created so it can never exceed one above the current
1016	     * maximum membership level among the other members of its household. The ceiling stored is that
1017	     * maximum plus one; the owner's derived {@link Owner#getMembershipLevel() membership level} is then
1018	     * never reported above it. An owner that joined no existing household - it has no {@code householdId}
1019	     * or is the sole member of its household - is left uncapped so no ceiling applies.
1020	     *
1021	     * @param owner the owner being created, with its {@code householdId} already resolved
1022	     */
1023	    private void applyMembershipLevelCeiling(Owner owner) {
1024	        String householdId = owner.getHouseholdId();
1025	        if (householdId == null) {
1026	            return;
1027	        }
1028	        OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
1029	            .filter(existing -> !existing.isDeleted())
1030	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
1031	            .mapToInt(this::currentMembershipLevel)
1032	            .max();
1033	        if (maxLevel.isPresent()) {
1034	            owner.setMembershipLevelCeiling(maxLevel.getAsInt() + 1);
1035	        }
1036	    }
1037	
1038	    /**
1039	     * The membership level an existing owner currently reports, computed the same way as for a response
1040	     * by first populating its {@link Owner#getHouseholdMemberCount() household member count}.
1041	     *
1042	     * @param member the existing household member whose membership level is needed
1043	     * @return the member's current membership level
1044	     */
1045	    private int currentMembershipLevel(Owner member) {
1046	        member.setHouseholdMemberCount(countHouseholdMembers(member));
1047	        return member.getMembershipLevel();
1048	    }
1049	
1050	    /**
1051	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
1052	     * last name and a postcode: the {@code householdId} is derived deterministically from the
1053	     * normalized last name and the postcode (see {@link #generateHouseholdId(String, String)}), so two
1054	     * owners with the same last name and postcode always resolve to the same identifier and belong to
1055	     * the same household automatically - no acknowledgement is needed to create the link.
1056	     * <p>
1057	     * When the owner supplies a postcode its {@code householdId} is always assigned; an owner with no
1058	     * postcode belongs to no household and is left without an identifier. Joining an existing household
1059	     * is not itself a conflict: hard duplicate detection is handled solely by the identity key (see
1060	     * {@link #rejectDuplicateIdentity(Owner)}), so two members of one household with different
1061	     * telephones are both created. An owner that explicitly acknowledges an existing household via
1062	     * {@code sharesHousehold} is reported as a declared member so it is not flagged as a possible
1063	     * duplicate.
1064	     *
1065	     * @param owner the owner being created
1066	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
1067	     * @return {@code true} when the owner joined an existing household as a declared member, otherwise
1068	     *         {@code false}
1069	     */
1070	    private boolean applyHousehold(Owner owner, Boolean sharesHousehold) {
1071	        String postcode = owner.getPostcode();
1072	        if (postcode == null || postcode.isBlank()) {
1073	            return false;
1074	        }
1075	        String lastName = normalizeHouseholdField(owner.getLastName());
1076	        String householdId = generateHouseholdId(lastName, postcode);
1077	        owner.setHouseholdId(householdId);
1078	        boolean hasExistingMember = this.clinicService.findAllOwners().stream()
1079	            .filter(existing -> !existing.isDeleted())
1080	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
1081	        return hasExistingMember && Boolean.TRUE.equals(sharesHousehold);
1082	    }
1083	
1084	    /**
1085	     * Builds the stable identifier shared by the members of one household. It is derived purely from
1086	     * the normalized last name and the postcode, so every owner sharing a last name and postcode
1087	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
1088	     * two fields joined by a single '|'.
1089	     *
1090	     * @param normalizedLastName the household's last name, already normalized for comparison
1091	     * @param postcode the household's postcode
1092	     * @return the shared household identifier
1093	     */
1094	    private String generateHouseholdId(String normalizedLastName, String postcode) {
1095	        String key = normalizedLastName + '|' + postcode;
1096	        try {
1097	            byte[] digest = MessageDigest.getInstance("SHA-256")
1098	                .digest(key.getBytes(StandardCharsets.UTF_8));
1099	            StringBuilder hex = new StringBuilder();
1100	            for (byte b : digest) {
1101	                hex.append(String.format("%02X", b));
1102	                if (hex.length() >= 12) {
1103	                    break;
1104	                }
1105	            }
1106	            return hex.substring(0, 12);
1107	        } catch (NoSuchAlgorithmException e) {
1108	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
1109	        }
1110	    }
1111	
1112	    /**
1113	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the given
1114	     * input's UTF-8 bytes. Used to derive the customer code's stable, deterministic hash component from
1115	     * the owner's normalized telephone and last name.
1116	     *
1117	     * @param input the string to digest
1118	     * @param length the number of leading upper-case hex characters to return
1119	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
1120	     */
1121	    private String sha256UpperHex(String input, int length) {
1122	        try {
1123	            byte[] digest = MessageDigest.getInstance("SHA-256")
1124	                .digest(input.getBytes(StandardCharsets.UTF_8));
1125	            StringBuilder hex = new StringBuilder();
1126	            for (byte b : digest) {
1127	                hex.append(String.format("%02X", b));
1128	                if (hex.length() >= length) {
1129	                    break;
1130	                }
1131	            }
1132	            return hex.substring(0, length);
1133	        } catch (NoSuchAlgorithmException e) {
1134	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
1135	        }
1136	    }
1137	
1138	    /**
1139	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
1140	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
1141	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
1142	     * expands common abbreviations.
1143	     *
1144	     * @param value the raw last name, or {@code null}
1145	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
1146	     */
1147	    private String normalizeHouseholdField(String value) {
1148	        if (value == null) {
1149	            return "";
1150	        }
1151	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1152	    }
1153	}
