333	    /**
334	     * The fiscal year in which a date falls, where the fiscal year starts on 1 July. A date on or after
335	     * 1 July belongs to the fiscal year ending in the following calendar year; a date before 1 July
336	     * belongs to the fiscal year ending in that same calendar year. The returned value is the fiscal
337	     * year's ending calendar year (e.g. {@code 2026-08-10} yields {@code 2027}, {@code 2026-05-10}
338	     * yields {@code 2026}).
339	     *
340	     * @param date the date to classify
341	     * @return the ending calendar year of the fiscal year the date falls in
342	     */
343	    public static int fiscalYear(LocalDate date) {
344	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
345	    }
346	
347	    /**
348	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the last two digits of the fiscal
349	     * year (which starts on 1 July) that the business-day-adjusted {@code registrationDate} falls in
350	     * (e.g. a registration date of {@code 2026-08-10} yields {@code 'FY27'}). It is a derived,
351	     * non-persistent value; when no {@code registrationDate} is present it is {@code null}.
352	     *
353	     * @return the {@code 'FY<YY>'} fiscal year, or {@code null} when no registration date is present
354	     */
355	    public String getFiscalYear() {
356	        if (this.registrationDate == null) {
357	            return null;
358	        }
359	        return String.format("FY%02d", fiscalYear(this.registrationDate) % 100);
360	    }
361	
362	    /**
363	     * The owner's membership points, a non-negative score. It starts at 0 and accumulates: 2 points
364	     * when an email address is present, 1 point when the owner has no namesakes ({@code namesakeCount}
365	     * is zero), 2 points for a household of 3 or more members ({@code householdMemberCount} is at least
366	     * 3), and 3 points for tenure &mdash; the number of elapsed fiscal years (the fiscal year starts on
367	     * 1 July) from {@code registrationDate} to today &mdash; of more than 1.
368	     *
369	     * @return the derived membership points (0 or more)
370	     */
371	    public Integer getMembershipPoints() {
372	        int points = 0;
373	        if (this.email != null && !this.email.isBlank()) {
374	            points += 2;
375	        }
376	        if (this.namesakeCount != null && this.namesakeCount == 0) {
377	            points += 1;
378	        }
379	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
380	            points += 2;
381	        }
382	        if (this.registrationDate != null
383	            && fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate) > 1) {
384	            points += 3;
385	        }
386	        return points;
387	    }
388	
389	    /**
390	     * The owner's membership level, a number from 1 to 4, derived from {@link #getMembershipPoints()}:
391	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more
392	     * points. The result is then capped at the owner's {@link #getMembershipLevelCeiling() membership
393	     * level ceiling} when one is set, so a new owner never exceeds one above the highest level among the
394	     * other members of its household at the time it was created.
395	     *
396	     * @return the derived membership level (1 to 4), capped at the membership-level ceiling when set
397	     */
398	    public Integer getMembershipLevel() {
399	        int points = getMembershipPoints();
400	        int level;
401	        if (points >= 6) {
402	            level = 4;
403	        } else if (points >= 4) {
404	            level = 3;
405	        } else if (points >= 2) {
406	            level = 2;
407	        } else {
408	            level = 1;
409	        }
410	        if (this.membershipLevelCeiling != null && level > this.membershipLevelCeiling) {
411	            return this.membershipLevelCeiling;
412	        }
413	        return level;
414	    }
415	
416	    /**
417	     * The owner's age band, derived from {@code birthDate} computed against {@code registrationDate}:
418	     * {@code MINOR} when the owner is under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65
419	     * or older. It is a derived, non-persistent value; when no {@code birthDate} is present it is
420	     * {@code null}.
421	     *
422	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
423	     *         is present
424	     */
425	    public String getAgeBand() {
426	        if (this.birthDate == null) {
427	            return null;
428	        }
429	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
430	        int age = java.time.Period.between(this.birthDate, reference).getYears();
431	        if (age < 18) {
432	            return "MINOR";
433	        }
434	        if (age < 65) {
435	            return "ADULT";
436	        }
437	        return "SENIOR";
438	    }
439	
440	    /**
441	     * The owner's preferred contact channel, derived from the stored fields: {@code EMAIL} when an
442	     * email address is present, otherwise {@code PHONE}.
443	     *
444	     * @return {@code "EMAIL"} when an email address is present, otherwise {@code "PHONE"}
445	     */
446	    public String getContactPreference() {
447	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
448	    }
449	
450	    /**
451	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
452	     * lower-case SHA-256 hex digest over the owner's normalized telephone (empty when none), its
453	     * lower-cased email (empty when none) and the Soundex code of its last name, joined by {@code '|'}.
454	     * Because the telephone is part of the key, two members of the same household with different
455	     * telephones have different identity keys; only owners whose whole key is identical are duplicates.
456	     *
457	     * @return the SHA-256 hex identity key over {@code normalizedTelephone|lowerEmail|soundex(lastName)}
458	     */
459	    public String getIdentityKey() {
460	        String telephonePart = this.telephone == null ? "" : this.telephone;
461	        String emailPart = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
462	        String key = telephonePart + '|' + emailPart + '|' + soundex(getLastName());
463	        return sha256Hex(key);
464	    }
465	
466	    /** Lower-case index (a=0 .. z=25) to Soundex digit, using the standard Soundex code table. */
467	    private static final char[] SOUNDEX_MAP = "01230120022455012623010202".toCharArray();
468	
469	    /**
470	     * The standard (American) Soundex code of a name: its first letter followed by three digits, so
471	     * names that sound alike share a code (e.g. {@code "Robert"} and {@code "Rupert"} both yield
472	     * {@code "R163"}). Non-letters are ignored and case is irrelevant; a value with no letters yields
473	     * an empty string.
474	     *
475	     * @param value the name to encode, or {@code null}
476	     * @return the four-character Soundex code, or an empty string when the value holds no letters
477	     */
478	    public static String soundex(String value) {
479	        if (value == null) {
480	            return "";
481	        }
482	        StringBuilder letters = new StringBuilder();
483	        for (int i = 0; i < value.length(); i++) {
484	            char c = value.charAt(i);
485	            if (c >= 'A' && c <= 'Z') {
486	                letters.append(c);
487	            } else if (c >= 'a' && c <= 'z') {
488	                letters.append((char) (c - ('a' - 'A')));
489	            }
490	        }
491	        if (letters.length() == 0) {
492	            return "";
493	        }
494	        String s = letters.toString();
495	        char[] out = {'0', '0', '0', '0'};
496	        out[0] = s.charAt(0);
497	        char last = soundexCode(s, 0);
498	        int count = 1;
499	        for (int i = 1; i < s.length() && count < out.length; i++) {
500	            char mapped = soundexCode(s, i);
501	            if (mapped != 0) {
502	                if (mapped != '0' && mapped != last) {
503	                    out[count++] = mapped;
504	                }
505	                last = mapped;
506	            }
507	        }
508	        return new String(out);
509	    }
510	
511	    /**
512	     * The Soundex digit contributed by the letter at {@code index}, honouring the rule that two
513	     * like-coded consonants separated only by {@code 'H'} or {@code 'W'} count once: such a letter
514	     * returns the null character {@code 0} so the caller skips it without resetting the running code.
515	     */
516	    private static char soundexCode(String s, int index) {
517	        char mapped = SOUNDEX_MAP[s.charAt(index) - 'A'];
518	        if (index > 1 && mapped != '0') {
519	            char hw = s.charAt(index - 1);
520	            if (hw == 'H' || hw == 'W') {
521	                char pre = s.charAt(index - 2);
522	                if (SOUNDEX_MAP[pre - 'A'] == mapped || pre == 'H' || pre == 'W') {
523	                    return 0;
524	                }
525	            }
526	        }
527	        return mapped;
528	    }
529	
530	    /**
531	     * The lower-case SHA-256 hex digest of the given string's UTF-8 bytes, used to derive the
532	     * {@link #getIdentityKey() identity key}.
533	     *
534	     * @param input the string to digest
535	     * @return the 64-character lower-case hex SHA-256 digest
536	     */
537	    private static String sha256Hex(String input) {
538	        try {
539	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
540	            StringBuilder hex = new StringBuilder(digest.length * 2);
541	            for (byte b : digest) {
542	                hex.append(String.format("%02x", b));
543	            }
544	            return hex.toString();
545	        } catch (NoSuchAlgorithmException e) {
546	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
547	        }
548	    }
549	
550	    protected Set<Pet> getPetsInternal() {
551	        if (this.pets == null) {
552	            this.pets = new HashSet<>();
553	        }
554	        return this.pets;
555	    }
556	
557	    protected void setPetsInternal(Set<Pet> pets) {
558	        this.pets = pets;
559	    }
560	
561	    public List<Pet> getPets() {
562	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
563	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
564	        return Collections.unmodifiableList(sortedPets);
565	    }
566	
567	    public void setPets(List<Pet> pets) {
568	        this.pets = new HashSet<>(pets);
569	    }
570	
571	    public void addPet(Pet pet) {
572	        getPetsInternal().add(pet);
573	        pet.setOwner(this);
574	    }
575	
576	    /**
577	     * Return the Pet with the given name, or null if none found for this Owner.
578	     *
579	     * @param name to test
580	     * @return true if pet name is already in use
581	     */
582	    public Pet getPet(String name) {
583	        return getPet(name, false);
584	    }
585	
586	    /**
587	     * Return the Pet with the given name, or null if none found for this Owner.
588	     *
589	     * @param name to test
590	     * @return true if pet name is already in use
591	     */
592	    public Pet getPet(String name, boolean ignoreNew) {
593	        name = name.toLowerCase();
594	        for (Pet pet : getPetsInternal()) {
595	            if (!ignoreNew || !pet.isNew()) {
596	                String compName = pet.getName();
597	                compName = compName.toLowerCase();
598	                if (compName.equals(name)) {
599	                    return pet;
600	                }
601	            }
602	        }
603	        return null;
604	    }
605	
606	    public Pet getPet(Integer petId) {
607	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
608	    }
609	
610	    @Override
611	    public String toString() {
612	        return new ToStringCreator(this)
613	
614	            .append("id", this.getId())
615	            .append("new", this.isNew())
616	            .append("lastName", this.getLastName())
617	            .append("firstName", this.getFirstName())
618	            .append("address", this.address)
619	            .append("city", this.city)
620	            .append("telephone", this.telephone)
621	            .toString();
622	    }
623	}
